// Preparar contexto
//
// Unifica los dos disparadores en una sola forma. La diferencia:
//
//   · Manual  → la aplicación YA creó la fila de automation_runs y manda su
//               run_id. Ese run_id es el cerrojo del límite de 10 minutos.
//   · Cron    → no hay nadie que la haya creado, así que se genera aquí un
//               run_id y el endpoint digest-payload crea la fila si no existe
//               (TECHNICAL_SPEC §9).

const entrada = $input.first()?.json ?? {};
const cuerpo = entrada.body ?? entrada;

const esManual = typeof cuerpo.run_id === 'string' && cuerpo.run_id.length > 0;

return [{
  json: {
    run_id: esManual ? cuerpo.run_id : crypto.randomUUID(),
    flow: 'morning_digest',
    trigger: esManual ? 'manual' : 'scheduled',
  },
}];

// Firmar la petición de datos
//
// Cadena que se firma:  `${timestamp}.${nonce}.${cuerpoCrudo}`
// Para el GET de digest-payload el cuerpo es la CADENA VACÍA
// (TECHNICAL_SPEC §8, «Contratos de los endpoints de n8n»).
//
// Se usa Web Crypto (crypto.subtle), que existe como global en Node 18+ y
// funciona en n8n Cloud sin habilitar módulos extra.

const secreto = $vars.N8N_SHARED_SECRET;
const base    = $vars.APP_BASE_URL;

if (!secreto) throw new Error('Falta la variable N8N_SHARED_SECRET en n8n (Settings → Variables).');
if (!base)    throw new Error('Falta la variable APP_BASE_URL en n8n (Settings → Variables).');

const { run_id, flow, trigger } = $input.first().json;

const timestamp = String(Math.floor(Date.now() / 1000));
const nonce     = crypto.randomUUID();
const cuerpo    = '';

const codificador = new TextEncoder();
const clave = await crypto.subtle.importKey(
  'raw',
  codificador.encode(secreto),
  { name: 'HMAC', hash: 'SHA-256' },
  false,
  ['sign'],
);
const firma = await crypto.subtle.sign(
  'HMAC',
  clave,
  codificador.encode(`${timestamp}.${nonce}.${cuerpo}`),
);
const hex = [...new Uint8Array(firma)].map((b) => b.toString(16).padStart(2, '0')).join('');

return [{
  json: {
    run_id,
    flow,
    trigger,
    url: `${base.replace(/\/$/, '')}/api/n8n/digest-payload?run_id=${encodeURIComponent(run_id)}&trigger=${encodeURIComponent(trigger)}`,
    timestamp,
    nonce,
    signature: `sha256=${hex}`,
  },
}];

// Componer el correo de un vendedor.  TECHNICAL_SPEC §9.
//
// Sin datos de otros vendedores. Sin el teléfono completo del cliente.
// Texto y listas, sin gráficos.

const v = $json;

const eur = (n) =>
  new Intl.NumberFormat('es-ES', {
    style: 'currency', currency: 'EUR',
    minimumFractionDigits: 2, maximumFractionDigits: 2, useGrouping: 'always',
  }).format(Number(n ?? 0));

const pct = (n) =>
  n === null || n === undefined
    ? '—'
    : `${new Intl.NumberFormat('es-ES', { minimumFractionDigits: 1, maximumFractionDigits: 1 }).format(Number(n))} %`;

const hora = (iso) =>
  new Intl.DateTimeFormat('es-ES', {
    timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false,
  }).format(new Date(iso));

const fechaLarga = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid', weekday: 'long', day: 'numeric', month: 'long',
}).format(new Date());

const lineas = [];
lineas.push(`Hola, ${v.full_name}.`);
lineas.push('');

// 1 · Atrasadas
lineas.push('ATRASADAS');
if (!v.needs_attention || v.needs_attention.length === 0) {
  lineas.push('Nada atrasado. Buen trabajo.');
} else {
  for (const o of v.needs_attention) {
    const motivo = o.is_overdue
      ? 'acción vencida'
      : `${o.days_without_activity} ${o.days_without_activity === 1 ? 'día' : 'días'} sin actividad`;
    lineas.push(
      `· ${o.customer_name}${o.customer_company ? ` (${o.customer_company})` : ''} — ` +
      `${o.stage} — ${eur(o.estimated_amount)} — ${motivo}`,
    );
  }
}
lineas.push('');

// 2 · Para hoy
lineas.push('PARA HOY');
if (!v.due_today || v.due_today.length === 0) {
  lineas.push('No tienes acciones agendadas para hoy.');
} else {
  for (const o of v.due_today) {
    lineas.push(`· ${hora(o.next_action_at)} — ${o.customer_name} — ${o.stage} — ${eur(o.estimated_amount)}`);
  }
}
lineas.push('');

// 3 · Tu mes
const m = v.month ?? {};
lineas.push('TU MES');
if (m.quota_amount) {
  lineas.push(`Cerrado: ${eur(m.closed_amount)} de ${eur(m.quota_amount)} — ${pct(m.quota_percent)}`);
  lineas.push(`Te faltan ${eur(m.remaining_amount)}.`);
} else {
  lineas.push(`Cerrado: ${eur(m.closed_amount)}. Tu supervisor aún no ha fijado tu meta de este mes.`);
}
lineas.push('');
lineas.push('Importes sin IVA.');
lineas.push('');
lineas.push($('Firmar petición de datos').first().json.url.split('/api/')[0]);

return {
  json: {
    profile_id: v.profile_id,
    to: v.email,
    subject: `CRM-123 · Tu resumen del ${fechaLarga}`,
    text: lineas.join('\n'),
  },
};

// Contar y firmar el resultado.
//
// Se cuentan los envíos que Resend aceptó (respuesta con `id`). Los que
// fallaron no se cuentan, pero tampoco tumban el flujo: el nodo de envío
// continúa ante el error para que un correo malo no deje a los otros nueve
// sin resumen.

const secreto = $vars.N8N_SHARED_SECRET;
const base    = $vars.APP_BASE_URL;

const { run_id } = $('Preparar contexto').first().json;

const items = $input.all();
const enviados = items.filter((i) => i.json && i.json.id).length;
const fallidos = items.length - enviados;

const cuerpoObjeto = {
  run_id,
  status: enviados > 0 || items.length === 0 ? 'success' : 'failed',
  emails_sent: enviados,
};
if (fallidos > 0) {
  cuerpoObjeto.error_message = `${fallidos} de ${items.length} correos no se pudieron enviar.`;
}

// El cuerpo se firma como CADENA EXACTA y se envía esa misma cadena. Si se
// volviera a serializar por el camino, el orden de las claves o el espaciado
// cambiarían y la firma no cuadraría (TECHNICAL_SPEC §8).
const cuerpo = JSON.stringify(cuerpoObjeto);

const timestamp = String(Math.floor(Date.now() / 1000));
const nonce     = crypto.randomUUID();

const codificador = new TextEncoder();
const clave = await crypto.subtle.importKey(
  'raw', codificador.encode(secreto),
  { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'],
);
const firma = await crypto.subtle.sign(
  'HMAC', clave, codificador.encode(`${timestamp}.${nonce}.${cuerpo}`),
);
const hex = [...new Uint8Array(firma)].map((b) => b.toString(16).padStart(2, '0')).join('');

return [{
  json: {
    url: `${base.replace(/\/$/, '')}/api/n8n/digest-result`,
    cuerpo,
    timestamp,
    nonce,
    signature: `sha256=${hex}`,
  },
}];

// Informar de un fallo temprano.
//
// Se llega aquí si la petición de datos falló: firma inválida, aplicación
// caída, red. Sin este camino, la fila de automation_runs se quedaría en
// «running» para siempre y el límite de 10 minutos bloquearía los reintentos
// sin que nadie supiera por qué.

const secreto = $vars.N8N_SHARED_SECRET;
const base    = $vars.APP_BASE_URL;

const { run_id } = $('Preparar contexto').first().json;

const cuerpo = JSON.stringify({
  run_id,
  status: 'failed',
  emails_sent: 0,
  error_message: 'No se pudieron obtener los datos del resumen.',
});

const timestamp = String(Math.floor(Date.now() / 1000));
const nonce     = crypto.randomUUID();

const codificador = new TextEncoder();
const clave = await crypto.subtle.importKey(
  'raw', codificador.encode(secreto),
  { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'],
);
const firma = await crypto.subtle.sign(
  'HMAC', clave, codificador.encode(`${timestamp}.${nonce}.${cuerpo}`),
);
const hex = [...new Uint8Array(firma)].map((b) => b.toString(16).padStart(2, '0')).join('');

return [{
  json: {
    url: `${base.replace(/\/$/, '')}/api/n8n/digest-result`,
    cuerpo,
    timestamp,
    nonce,
    signature: `sha256=${hex}`,
  },
}];
